    if not man_patches:
        return "No man found in the image."

    # Sort man patches by their right coordinate to find the one on the rightmost side
    man_patches.sort(key=lambda patch: patch.right, reverse=True)
    man_on_right = man_patches[0]

    # Verify if the man is indeed on the right side of the image
    if man_on_right.right > image_patch.cropped_image.shape[1] / 2:
        return "Yes, there is a man on the right."
    else:
        return "No, the man is not on the right."

def find_right_man(image):
    image_patch = ImagePatch(image)
    men_patches = image_patch.find("man")

    if not men_patches:
        return "No men found in the image."

    # Assuming the image has a defined width, we need to determine the rightmost man
    max_right = -math.inf
    right_man_patch = None

    for man_patch in men_patches:
        if man_patch.right > max_right:
            max_right = man_patch.right
            right_man_patch = man_patch

    if right_man_patch:
        description = right_man_patch.simple_query("What is this man doing?")
        return f"The rightmost man is {description}."
    else:
        return "Could not determine the rightmost man."

def find_man_sitting_on_bench(image):
    image_patch = ImagePatch(image)
