def find_main_guy_on_tv(image):
    image_patch = ImagePatch(image)
    tv_patches = image_patch.find("tv")
    if not tv_patches:
        return "No TV found in the image."

    main_guy_patches = []
    for tv_patch in tv_patches:
        people_patches = tv_patch.find("person")
        for person_patch in people_patches:
            if person_patch.verify_property("person", "main character"):
                main_guy_patches.append(person_patch)

    if not main_guy_patches:
        return "No main guy found on the TV."

    # Assuming the main guy is the largest person in the TV frame
    main_guy_patch = max(main_guy_patches, key=lambda x: (x.right - x.left) * (x.upper - x.lower))

    description = main_guy_patch.simple_query("Who is this person?")
    if description == "This person is unknown":
        description = main_guy_patch.llm_query("Describe the person in the TV.", long_answer=False)

    return description

