                current_patch.crop(left=(current_patch.right + current_patch.left) // 2, lower=(current_patch.upper + current_patch.lower) // 2, right=current_patch.right, upper=current_patch.upper)
            ]
            patches.extend(sub_patches)
        elif current_patch.best_text_match(["black"]) != "black":
