        return "No guy found in the image."

    # Sort the guys based on their rightmost edge
    guy_patches.sort(key=lambda patch: patch.right, reverse=True)

    # The guy all the way right in front
    rightmost_guy = guy_patches[0]

    # Check if there are any guys overlapping with the rightmost guy
    for other_guy in guy_patches[1:]:
        if rightmost_guy.overlaps_with(other_guy.left, other_guy.lower, other_guy.right, other_guy.upper):
            # If they overlap, check which one is in front based on depth
            if rightmost_guy.compute_depth() > other_guy.compute_depth():
