def find_person_putting_hand_in_face(image):
    image_patch = ImagePatch(image)
    people_patches = image_patch.find("person")

    if len(people_patches) < 3:
        return "There are less than three people in the image."

    third_person = people_patches[2]  # Index 2 for third person from the left

    # Check if the third person is putting their hand in someone's face
    is_putting_hand_in_face = third_person.verify_property("hand", "in face")

    if not is_putting_hand_in_face:
        return "The third person from the left is not putting their hand in anyone's face."

    # Find the person whose face is being touched
    for person in people_patches:
        if person.overlaps_with(*third_person.crop(left=third_person.left, lower=third_person.lower, right=third_person.right, upper=third_person.upper).get_coordinates()):
            continue
        if person.verify_property("face", "touched by hand"):
            person_name = person.simple_query("Who is this person?")
            return f"The third person from the left is putting their hand in {person_name}'s face."

    return "Could not determine who the third person from the left is putting their hand in."

