def find_redhead_center(image):
    image_patch = ImagePatch(image)
    redhead_patches = image_patch.find("redhead")
    if not redhead_patches:
        return "No redhead found in the image."

    # Assuming we want the centermost redhead based on the bounding box coordinates
    center_x = image_patch.cropped_image.shape[1] / 2
    center_y = image_patch.cropped_image.shape[0] / 2

    def distance_from_center(patch):
        patch_center_x = (patch.left + patch.right) / 2
        patch_center_y = (patch.lower + patch.upper) / 2
        return math.sqrt((patch_center_x - center_x) ** 2 + (patch_center_y - center_y) ** 2)

    centermost_redhead = min(redhead_patches, key=distance_from_center)
    return centermost_redhead.simple_query("What is this?")

