def find_man_behind_luggage(image):
    image_patch = ImagePatch(image)
    people_patches = image_patch.find("man")
    luggage_patches = image_patch.find("luggage")

    man_behind_luggage = None
    min_distance = float('inf')

    for person in people_patches:
        for luggage in luggage_patches:
            if person.overlaps_with(luggage.left, luggage.lower, luggage.right, luggage.upper):
                continue
            if person.left < luggage.left:  # Man should be on the left side
                dist = distance(person, luggage)
                if dist < 0:  # Overlapping case
                    continue
                if dist < min_distance:
                    min_distance = dist
                    man_behind_luggage = person

    if man_behind_luggage:
        description = man_behind_luggage.simple_query("What is the man wearing?")
        if "black" in description.lower():
            return man_behind_luggage
    return None

