def find_man_in_front_of_other_man(image):
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")

    if len(man_patches) < 2:
        return "No two men found in the image."

    # Sort men by their vertical position (assuming lower means further back)
    man_patches.sort(key=lambda patch: patch.lower, reverse=True)

    man_in_front = man_patches[0]
    man_behind = man_patches[1]

    # Verify if they overlap horizontally
    def horizontal_overlap(patch1, patch2):
        return not (patch1.right < patch2.left or patch1.left > patch2.right)

    if not horizontal_overlap(man_in_front, man_behind):
        return "The men are not positioned side by side."

    return "The man in front of the other man is located at coordinates: left={}, lower={}, right={}, upper={}".format(
        man_in_front.left, man_in_front.lower, man_in_front.right, man_in_front.upper
    )

